	return 0;
}
```

* A C++ function to calculate the sum of an array:
```cpp
#include <iostream>

void sumArray(int arr[], int size) {
	int sum = 0;
	for (int i = 0; i < size; i++) {
		sum += arr[i];
	}
	std::cout << sum << std::endl;
}

int main() {
	int arr[] = {1, 2, 3, 4, 5};
	sumArray(arr, 5); // Output: 15
	return 0;
}
```

